package com.keepcalm.placementportal.controller;import com.keepcalm.placementportal.models.round.RoundDtos.*;import com.keepcalm.placementportal.service.RoundService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/admin/drives/{driveId}/rounds")@RequiredArgsConstructor public class RoundController{private final RoundService service;@GetMapping public List<RoundDto> list(@PathVariable Long driveId){return service.list(driveId);}@PostMapping @ResponseStatus(HttpStatus.CREATED)public RoundDto create(@PathVariable Long driveId,@Valid@RequestBody Upsert r){return service.create(driveId,r);}@PutMapping("/{roundId}")public RoundDto update(@PathVariable Long driveId,@PathVariable Long roundId,@Valid@RequestBody Upsert r){return service.update(driveId,roundId,r);}@DeleteMapping("/{roundId}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable Long driveId,@PathVariable Long roundId){service.delete(driveId,roundId);}@GetMapping("/{roundId}/participants")public List<ParticipantDto> participants(@PathVariable Long driveId,@PathVariable Long roundId){return service.participants(driveId,roundId);}@PostMapping("/{roundId}/results")public Map<String,Object> results(@PathVariable Long driveId,@PathVariable Long roundId,@Valid@RequestBody Results r){return service.saveResults(driveId,roundId,r);}@PostMapping("/{roundId}/publish-results")public RoundDto publish(@PathVariable Long driveId,@PathVariable Long roundId){return service.publish(driveId,roundId);}}
